package com.medtrack.inventory.service;
import com.medtrack.inventory.entity.*; import com.medtrack.inventory.repository.InventoryBalanceRepository; import com.medtrack.shared.exception.*; import com.medtrack.user.entity.User; import com.medtrack.warehouse.entity.*; import java.util.*; import org.springframework.stereotype.Service;
@Service public class InventoryMovementService {private final InventoryBalanceRepository balances;private final DoubleEntryLedgerService ledger;private final CriticalAuditService audit; public InventoryMovementService(InventoryBalanceRepository b,DoubleEntryLedgerService l,CriticalAuditService a){balances=b;ledger=l;audit=a;} public void dispatch(User actor,UUID reference,List<Allocation> allocations){List<InventoryLedgerLine> lines=new ArrayList<>();for(Allocation a:allocations){InventoryBalance b=balances.lockByWarehouseAndBatch(a.source().getId(),a.batchId()).orElseThrow(()->new NotFoundException("Inventory balance"));if(b.getReservedQuantity()<a.quantity())throw new DomainException("INSUFFICIENT_RESERVED_STOCK","Reserved stock is unavailable for dispatch");lines.add(InventoryLedgerLine.physical(b.getBatch(),a.source(),LedgerDirection.CREDIT,a.quantity(),b,0,-a.quantity(),0));lines.add(InventoryLedgerLine.offset(b.getBatch(),AccountType.IN_TRANSIT,LedgerDirection.DEBIT,a.quantity()));b.dispatch(a.quantity());}InventoryJournalEntry e=ledger.record(JournalEntryType.TRANSFER_DISPATCH,"STOCK_TRANSFER",reference,actor,"Transfer dispatch",lines);audit.record(actor.getId(),"TRANSFER_DISPATCH","INVENTORY_JOURNAL_ENTRY",e.getId(),"{}");} public void receive(User actor,UUID reference,Warehouse destination,StorageLocation location,List<Receipt> receipts){List<InventoryLedgerLine> lines=new ArrayList<>();for(Receipt r:receipts){InventoryBalance b=balances.findByWarehouse_IdAndBatch_Id(destination.getId(),r.batchId()).orElseGet(()->new InventoryBalance(destination,r.batch(),location));lines.add(InventoryLedgerLine.physical(r.batch(),destination,LedgerDirection.DEBIT,r.quantity(),b,r.quantity(),0,0));lines.add(InventoryLedgerLine.offset(r.batch(),AccountType.IN_TRANSIT,LedgerDirection.CREDIT,r.quantity()));b.receive(r.quantity());balances.save(b);}InventoryJournalEntry e=ledger.record(JournalEntryType.TRANSFER_RECEIVE,"STOCK_TRANSFER",reference,actor,"Transfer receipt",lines);audit.record(actor.getId(),"TRANSFER_RECEIVE","INVENTORY_JOURNAL_ENTRY",e.getId(),"{}");} public void releaseReservations(User actor,UUID reference,Warehouse source,List<Allocation> allocations){if(allocations==null||allocations.isEmpty())return;List<InventoryLedgerLine> lines=new ArrayList<>();for(Allocation a:allocations){InventoryBalance b=balances.lockByWarehouseAndBatch(source.getId(),a.batchId()).orElseThrow(()->new NotFoundException("Inventory balance"));if(b.getReservedQuantity()<a.quantity())throw new DomainException("INSUFFICIENT_RESERVED_STOCK","Reserved stock is insufficient for release");lines.add(InventoryLedgerLine.physical(b.getBatch(),source,LedgerDirection.DEBIT,a.quantity(),b,a.quantity(),-a.quantity(),0));lines.add(InventoryLedgerLine.offset(b.getBatch(),AccountType.AUDIT_SURPLUS_OFFSET,LedgerDirection.CREDIT,a.quantity()));b.release(a.quantity());}InventoryJournalEntry e=ledger.record(JournalEntryType.STOCK_ADJUSTMENT,"STOCK_TRANSFER",reference,actor,"Release reserved stock for transfer cancellation",lines);audit.record(actor.getId(),"TRANSFER_CANCEL_RELEASE","INVENTORY_JOURNAL_ENTRY",e.getId(),"{}");} public record Allocation(UUID batchId,int quantity,Warehouse source){} public record Receipt(UUID batchId,com.medtrack.batch.entity.Batch batch,int quantity){} }

